""";
    private static readonly JsonDocument Catalog = JsonDocument.Parse(CatalogJson);
    private static readonly string[] NavigationSignals = ["where", "how do i", "how to", "button", "click", "find", "open", "page", "tab", "screen", "navigate", "ở đâu", "chỗ nào", "nút", "nhấn", "bấm", "vào đâu", "làm sao", "cách", "trang nào", "mở", "tìm"];
    private static string Normalize(string value)
    {
        var decomposed = (value ?? "").Normalize(NormalizationForm.FormD);
        var builder = new StringBuilder();
        foreach (var c in decomposed)
        {
            if (CharUnicodeInfo.GetUnicodeCategory(c) != UnicodeCategory.NonSpacingMark)
                builder.Append(c == 'đ' || c == 'Đ' ? 'd' : char.ToLowerInvariant(c));
        }
        return Regex.Replace(builder.ToString().Normalize(NormalizationForm.FormC), @"[^a-z0-9]+", " ").Trim();
    }
    internal static bool IsNavigationQuestion(string question)
    {
        var q = Normalize(question);
        if (q.Length == 0) return false;
        return NavigationSignals.Any(signal =>
        {
            var token = Normalize(signal);
            return token.Length > 0 && (" " + q + " ").Contains(" " + token + " ", StringComparison.Ordinal);
        }) || Regex.IsMatch(q, @"\b(huong dan|thao tac|chuc nang|quan ly|cai dat|tai khoan|create|manage|settings)\b");
    }

    internal static string? TryAnswer(string question, string role)
    {
        if (role is not ("member" or "coach") || !IsNavigationQuestion(question)) return null;
        var q = Normalize(question);
        JsonElement best = default;
        double bestScore = 0;
        foreach (var item in Catalog.RootElement.EnumerateArray())
        {
            if (!string.Equals(item.GetProperty("role").GetString(), role, StringComparison.OrdinalIgnoreCase)) continue;
            double score = 0;
            foreach (var keyword in item.GetProperty("keywords").EnumerateArray())
            {
                var k = Normalize(keyword.GetString() ?? "");
                if (k.Length >= 3 && (" " + q + " ").Contains(" " + k + " ", StringComparison.Ordinal))
                    score = Math.Max(score, k.Split(' ').Length * 2.0 + k.Length / 20.0);
            }
            // Prefer concrete actions over generic page matches.
            if (item.GetProperty("kind").GetString() == "action") score += score > 0 ? 0.6 : 0;
            if (score > bestScore) { best = item; bestScore = score; }
        }
        if (bestScore < 2.2) return null;
        var title = best.GetProperty("title").GetString();
        var route = best.GetProperty("route").GetString();
        var lines = best.GetProperty("steps").EnumerateArray().Select((x,i) => $"{i+1}. {x.GetString()}");
        return $"SportHub — {title} ({route})\n" + string.Join("\n", lines);
    }

    // The catalog may omit a button or an exact path. Do not falsely say SportHub cannot help;
    // respond with an appropriate role-level starting point and explicitly mark uncertainty.
    internal static string NavigationFallback(string question, string role)
    {
        if (role is not ("member" or "coach")) return "Navigation assistance is only enabled for Member and Coach.";
        var q = Normalize(question);
        var account = q.Contains("tai khoan", StringComparison.Ordinal) || q.Contains("account", StringComparison.Ordinal)
            || q.Contains("profile", StringComparison.Ordinal) || q.Contains("mat khau", StringComparison.Ordinal);
        if (account)
            return "Để quản lý tài khoản SportHub: 1. Mở menu hồ sơ/ảnh đại diện trên thanh điều hướng. " +
                   "2. Mở Account (/account). 3. Trong trang Account, chọn phần thông tin hồ sơ hoặc đổi mật khẩu tương ứng. " +
                   "Chỉ các thao tác và trường mà tài khoản của bạn được phép chỉnh sửa mới khả dụng.";
        var start = role switch
        {
            "coach" => "Classes (/coach/classes) hoặc Schedule (/coach/schedule)",
            "member" => "Member workspace (/member)",
            _ => "SportHub workspace"
        };
        return $"Đây là câu hỏi hướng dẫn thao tác trên SportHub. Hãy bắt đầu tại {start}. " +
               "Tôi chưa có hướng dẫn đã xác minh cho đúng nút bạn hỏi; bạn có thể nêu tên chức năng hoặc trang đang mở để tôi chỉ chính xác hơn.";
    }
